=======
def get_chunksizes(
    variables: Iterable[Variable],
) -> Mapping[Any, tuple[int, ...]]:

    """
    Return a mapping from dimension name to chunk size for a collection of
    Variables.

    This function inspects the underlying array *without* triggering a full
    load of the data.  For variables backed by dask arrays we use the ``chunks``
    attribute.  For variables that store chunk information in their ``encoding``
    (e.g. ZarrArrayWrapper), we extract the chunk sizes from ``encoding["chunks"]``
    which is a tuple aligned with ``v.dims``.
    """
    chunks: dict[Any, tuple[int, ...]] = {}
    for v in variables:
        # Prefer the low‑level ``_data`` attribute to avoid loading the full array.
        data = getattr(v, "_data", None)

        # Case 1: underlying array (e.g. dask) provides a ``chunks`` attribute.
        if data is not None and hasattr(data, "chunks"):
            for dim, c in v.chunksizes.items():
                if dim in chunks and c != chunks[dim]:
                    raise ValueError(
                        f"Object has inconsistent chunks along dimension {dim}. "
                        "This can be fixed by calling unify_chunks()."
                    )
                chunks[dim] = c

        # Case 2: chunk information stored in the variable's encoding (e.g. Zarr).
        elif "chunks" in getattr(v, "encoding", {}):
            # ``encoding["chunks"]`` is a tuple of chunk sizes ordered like ``v.dims``.
            for dim, c in zip(v.dims, v.encoding["chunks"]):
                if dim in chunks and c != chunks[dim]:
                    raise ValueError(
                        f"Object has inconsistent chunks along dimension {dim}. "
                        "This can be fixed by calling unify_chunks()."
